package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamFirstAidBank2 {
    private const val T = "ප්‍රථමාධාර, හදිසි අනතුරු හා ක්‍රීඩා ආබාධ කළමනාකරණය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("වළලුකර, දණහිස හෝ වැළමිට වැනි චලනය වන සන්ධියක් වෙළීම සඳහා වඩාත් සුදුසු බැන්ඩේජ් වෙළුම් ක්‍රමය කුමක්ද?", "අටේ හැඩයේ වෙළුම (Figure-of-eight bandage)", "චක්‍රාකාර වෙළුම", "සර්පිලාකාර වෙළුම", "ප්‍රත්‍යාවර්තක වෙළුම", "අටේ හැඩයේ වෙළුම සන්ධියේ නම්‍යශීලී බව ආරක්ෂා කරමින් මනා ආධාරකයක් සපයයි."),
        q("කෙණ්ඩ හෝ පෙරබාහුව වැනි සමාන ඝනකමක් නොමැති කේතුකාකාර අවයවයක් වෙළීම සඳහා යොදා ගන්නා වෙළුම් ක්‍රමය කුමක්ද?", "ප්‍රතිවර්තිත සර්පිලාකාර වෙළුම (Spiral reverse bandage)", "චක්‍රාකාර වෙළුම", "අටේ හැඩයේ වෙළුම", "කරපටි වෙළුම", "ක්‍රමයෙන් මහත් වන අවයවවල වෙළුම් පටිය නොලිස්සා තබා ගැනීමට ප්‍රතිවර්තිත සර්පිලාකාර වෙළුම යොදා ගැනේ."),
        q("හිස් මුදුනේ තුවාලයක් හෝ කපා වෙන් වූ අවයවයක අග්‍රය වෙළීම සඳහා භාවිත කරන විශේෂ වෙළුම් ක්‍රමය කුමක්ද?", "ප්‍රත්‍යාවර්තක වෙළුම (Recurrent bandage)", "සර්පිලාකාර වෙළුම", "චක්‍රාකාර වෙළුම", "අටේ හැඩයේ වෙළුම", "හිසේ හෝ ඇඟිලි තුඩුවල හැඩයට ගැලපෙන සේ ඉදිරියට හා පසුපසට නමමින් යොදන වෙළුම ප්‍රත්‍යාවර්තක වෙළුමයි."),
        q("පිහියක් හෝ වීදුරු කැබැල්ලක් වැනි තියුණු ආයුධයකින් කැපී ගිය පැහැදිලි සිනිඳු දාර සහිත තුවාලය කුමක්ද?", "කැපුම් තුවාලය (Incised wound)", "ඉරුණු තුවාලය", "විදුම් තුවාලය", "තැලීම් තුවාලය", "තියුණු දාරවලින් කැපෙන තුවාලවල දාර සිනිඳු වන අතර රුධිර වහනය බහුලව සිදුවේ."),
        q("රළු හෝ මොට මතුපිටක ගැටීමෙන් සම අක්‍රමවත් ලෙස ඉරී ගිය අසමාන දාර සහිත තුවාලය කුමක්ද?", "ඉරුණු තුවාලය (Lacerated wound)", "කැපුම් තුවාලය", "විදුම් තුවාලය", "සීරීම් තුවාලය", "මෝටර් රථ අනතුරු හෝ යන්ත්‍ර සූත්‍රවලින් සිදුවන අනතුරුවලදී අක්‍රමවත් දාර සහිත ඉරුණු තුවාල හටගනී."),
        q("මලකඩ කෑ ඇණයක්, කටුවක් හෝ ඉදිකටුවක් ශරීරය තුළට ගැඹුරට කිඳා බැසීමෙන් හටගන්නා තුවාලය කුමක්ද?", "විදුම් තුවාලය (Puncture wound)", "සීරීම් තුවාලය", "කැපුම් තුවාලය", "තැලුම් තුවාලය", "විදුම් තුවාල මතුපිටින් කුඩා වුවද ගැඹුරට විහිදෙන බැවින් පිටගැස්ම ආසාදන අවදානම ඉතා ඉහළය."),
        q("බිම ඇද වැටී රළු පොළොවේ ඇතිල්ලීම නිසා සමේ උඩම අපිචර්ම ස්ථරය පමණක් ගැලවී යන තුවාලය කුමක්ද?", "සීරීම් තුවාලය (Abrasion)", "විදුම් තුවාලය", "ඉරුණු තුවාලය", "ගැඹුරු කැපුම", "මතුපිට ස්ථරය සීරී යාමෙන් හටගන්නා සීරීම් තුවාලවලින් ලේ බිංදු සෙමෙන් කාන්දු වේ."),
        q("සම මතුපිට නොකැඩී අභ්‍යන්තර රුධිර වාහිනී පිපිරීමෙන් සම යට ලේ එකතු වී නිල් හෝ කළු පැහැ ගැන්වීම කුමක්ද?", "තැලීම් තුවාලය හෙවත් බෲස් වීම (Contusion / Bruise)", "කැපුම් තුවාලය", "විදුම් තුවාලය", "ඉරුණු තුවාලය", "මොට පහරක් වැදීමෙන් සම යට කේශනාලිකා කැඩී ලේ කැටි ගැසීම තැලුම් තුවාලයකි."),
        q("මලකඩ කෑ යකඩ ඇණයක් ඇනීමෙන් හෝ අපිරිසිදු පස් තැවරුණු ගැඹුරු තුවාලයකදී ලබාදිය යුතු අනිවාර්ය එන්නත කුමක්ද?", "පිටගැස්ම ප්‍රතිශක්තිකරණ එන්නත (Tetanus Toxoid — TT)", "ජලභීතිකා එන්නත", "පෝලියෝ එන්නත", "BCG එන්නත", "පස්වල සිටින Clostridium tetani බැක්ටීරියාවෙන් ආරක්ෂා වීමට පිටගැස්ම එන්නත (TT) ලබාගත යුතුය."),
        q("බල්ලෙකු හෝ පූසෙකු සපා කෑ වහාම තුවාලයට ලබාදිය යුතු අත්‍යවශ්‍යම ක්ෂණික ප්‍රථමාධාරය කුමක්ද?", "ගලා යන පිරිසිදු නළ ජලය සහ සබන් යොදා විනාඩි 15ක් පමණ තුවාලය හොඳින් සේදීම", "තුවාලය වහාම මසා දැමීම", "තුවාලය මත තෙල් ආලේප කිරීම", "තුවාලය තදින් වෙළා බැඳීම", "ජලභීතිකා වෛරසය සබන් හා ගලා යන ජලයෙන් සෝදා හැරීම මගින් ආසාදන අවදානම 80%කින් පමණ පහත වැටේ."),
        q("සතෙකු සපා කෑ තුවාලයක් සම්බන්ධයෙන් වෛද්‍යවරුන් සාමාන්‍යයෙන් නිර්දේශ නොකරන පියවර කුමක්ද?", "තුවාලය වහාම මැහුම් දමා වසා දැමීම", "සබන් දමා සේදීම", "ප්‍රතිජීවක ලබාදීම", "ජලභීතිකා එන්නත දීම", "සපා කෑ විෂබීජ තුවාලය තුළ සිරවන බැවින් එවැනි තුවාල වහාම මැහුම් දමා වසා නොදමයි."),
        q("අධික රස්නය හා සූර්යාලෝකය සහිත පරිසරයක අධික ලෙස දහඩිය දැමීම නිසා හටගන්නා ක්ලාන්ත ගතිය කුමක්ද?", "තාප විඩාව (Heat Exhaustion)", "තාප ආඝාතය", "අධිශීතලතාව", "හිම පිළිස්සුම", "විජලනය හා ලවණ අහිමි වීම නිසා සම සීතල වී, ක්ලාන්තය හා දැඩි පිපාසය ඇතිවීම තාප විඩාවයි."),
        q("දහඩිය දැමීම සම්පූර්ණයෙන්ම නැවතී ශරීර උෂ්ණත්වය සෙල්සියස් 40 ඉක්මවා යන මාරාන්තික හදිසි තත්ත්වය කුමක්ද?", "තාප ආඝාතය (Heat Stroke)", "තාප විඩාව", "සෙම්ප්‍රතිශ්‍යාව", "උළුක්කුව", "තාප ආඝාතයේදී ශරීරයේ උෂ්ණත්ව පාලන පද්ධතිය බිඳ වැටී සම වියළි වී රතු වන අතර වහාම රෝහල්ගත කළ යුතුය."),
        q("තාප ආඝාතයට (Heat Stroke) ලක් වූ රෝගියෙකුගේ ශරීර උෂ්ණත්වය ක්ෂණිකව පහත හෙළීමට කළ යුතු ප්‍රධාන පියවර කුමක්ද?", "සිසිල් සෙවණකට ගෙන ගොස් ඇඳුම් ලිහිල් කර තෙත රෙදි කඩකින් සිරුර පිස දැමීම හෝ සිසිල් ජලය ඉසීම", "උණුසුම් බ්ලැන්කට් පොරවීම", "උණු තේ පෙවීම", "අව්වේම තබා තැබීම", "මොළයට වන හානිය වැළැක්වීමට රෝගියා සීතල ජලයෙන් හෝ තෙත රෙදිවලින් ආවරණය කර ඉක්මනින් සිසිල් කළ යුතුය."),
        q("අධික ශීතල පරිසරයක රැඳී සිටීම නිසා ශරීරයේ අභ්‍යන්තර උෂ්ණත්වය සෙල්සියස් 35ට වඩා පහත වැටීම හඳුන්වන්නේ කෙසේද?", "අධිශීතලතාව (Hypothermia)", "තාප ආඝාතය", "කම්පනය", "උණ සන්නිපාතය", "සිරුරේ උෂ්ණත්වය සෙ.මී. 35ට වඩා අඩු වූ විට වෙව්ලීම, සිහිවිකල් බව හා නිදිමත ගතිය හටගනී."),
        q("ඇස තුළට දූවිලි අංශුවක් හෝ වැලි කැටයක් වැටුණු විට කිසිසේත්ම නොකළ යුත්තේ කුමක්ද?", "ඇස තදින් අතුල්ලා පිස දැමීම", "පිරිසිදු ඇල් ජලයෙන් සේදීම", "නිතර ඇසිපිය ගැසීම", "වෛද්‍යවරයෙකු වෙත යාම", "ඇස අතුල්ලන විට දූවිලි අංශුව කනිනිකාව (Cornea) මත සීරී ස්ථිර පෙනීමේ ආබාධ ඇතිවිය හැක."),
        q("ඇස තුළට රසායනික ද්‍රව්‍යයක් විසි වූ විට ඇස සේදිය යුතු නිවැරදි දිශානතිය කුමක්ද?", "නාසය දෙසින් (ඇතුළු කොනෙන්) පිටත කණ දෙසට ජලය ගලා යන පරිදි සේදීම", "පිටත කොනේ සිට නාසය දෙසට සේදීම", "අනෙක් නිරෝගී ඇස දෙසට ගලා යන සේ සේදීම", "දෑස් තද කර පියාගෙන සිටීම", "නිරෝගී අනෙක් ඇසට රසායනික දියර කාන්දු වීම වැළැක්වීමට ඇතුළත සිට පිටතට ජලය ගලා යා යුතුය."),
        q("ක්‍රීඩාවේදී හෝ අනතුරකදී පුද්ගලයෙකුගේ දතක් මුලින්ම ගැලවී ගියහොත් (Avulsed tooth) කළ යුතු නිවැරදි ප්‍රථමාධාරය කුමක්ද?", "දතේ මුල නොඅල්ලා ඔටුන්නෙන් අල්ලා නැවුම් එළකිරි හෝ ඛේටය තුළ බහා විනාඩි 30-60ක් ඇතුළත දන්ත වෛද්‍යවරයා වෙත රැගෙන යාම", "දත සබන් දමා හොඳින් බ්‍රෂ් කර සේදීම", "දත අව්වේ වේලා ගැනීම", "දත කඩදාසියක ඔතා සාක්කුවේ දැමීම", "දතේ මුලේ ඇති ජීවී සෛල ආරක්ෂා කර ගැනීමට කිරි හෝ ඛේටය තුළ බහා වහාම දන්ත වෛද්‍යවරයා හමුවිය යුතුය."),
        q("මීමැස්සෙකු දෂ්ට කිරීමෙන් හෝ ඖෂධයකින් පසු හදිසියේම හුස්ම ගැනීමේ අපහසුව හා සිරුර ඉදිමීම ඇතිවන දරුණු අසාත්මිකතාව කුමක්ද?", "ඇනෆිලැක්සිස් හෙවත් දරුණු ආසාත්මිකතා කම්පනය (Anaphylaxis)", "සාමාන්‍ය පීනස", "තාප විඩාව", "ආහාර අජීර්ණය", "ඇනෆිලැක්සිස් යනු රුධිර පීඩනය ක්ෂණිකව පහත වැටී ශ්වාසනාල ඉදිමී හුස්ම හිරවන මාරාන්තික තත්ත්වයකි."),
        q("ඇනෆිලැක්සිස් (Anaphylaxis) හදිසි තත්ත්වයකදී රෝගියාට ක්ෂණිකව ලබාදිය යුතු ජීවිතාරක්ෂක ඖෂධය කුමක්ද?", "ඇඩ්‍රිනලින් හෙවත් එපිනෙෆ්‍රින් (Adrenaline / Epinephrine Auto-injector)", "පැරසිටමෝල්", "ඉන්සියුලින්", "ඇස්ප්‍රින්", "කලව ප්‍රදේශයට විදින ඇඩ්‍රිනලින් එන්නත මගින් ක්ෂණිකව ශ්වසන මාර්ග විවෘත කර රුධිර පීඩනය සාමාන්‍ය කරයි."),
        q("ඇදුම රෝගියෙකුට හදිසි හුස්ම ගැනීමේ අපහසුතාවක් (Asthma attack) ඇතිවූ විට කළ යුතු නිවැරදි පියවර කුමක්ද?", "රෝගියා කෙළින් වාඩි කරවා සහනදායී ආශ්වාසකය (Reliever / Salbutamol Inhaler) ලබාදීම", "රෝගියා උඩුබැලි අතට බිම දිගා කිරීම", "සීතල වතුර පෙවීම", "රෝගියා දුවවීමට සැලැස්වීම", "කෙළින් වාඩි වී සිටින විට පෙණහලුවලට උපරිම ඉඩ ලැබෙන අතර ඉන්හේලරය මගින් ශ්වාසනාල ප්‍රසාරණය වේ."),
        q("දියවැඩියා රෝගියෙකුගේ රුධිර සීනි මට්ටම භයානක ලෙස පහත වැටීම (Hypoglycaemia) හඳුනාගත හැකි ලක්ෂණ මොනවාද?", "අධික ලෙස වෙව්ලීම, දහඩිය දැමීම, බඩගින්න සහ සිහිවිකල් ගතිය", "අධික පිපාසය පමණක් ඇතිවීම", "සම වියළි වී රතු වීම", "ගැඹුරු මන්දගාමී හුස්ම ගැනීම", "සීනි අඩුවූ විට මොළයට ග්ලූකෝස් නොලැබී දහඩිය දැමීම හා වෙව්ලීම සමග ක්ලාන්තය ඇතිවේ."),
        q("සිහිය ඇති අඩු රුධිර සීනි (Hypoglycaemia) රෝගියෙකුට ක්ෂණිකව ලබාදිය යුතු ප්‍රථමාධාරය කුමක්ද?", "පැණි බීමක්, ග්ලූකෝස් හෝ සීනි සහිත රසකැවිල්ලක් කෑමට දීම", "ඉන්සියුලින් එන්නත් කිරීම", "ලුණු වතුර පෙවීම", "කිසිවක් නොදී නිදා ගැනීමට සැලැස්වීම", "ක්ෂණිකව රුධිරයට උරා ගන්නා සීනි සහිත පානයක් දීමෙන් මොළය අකර්මණ්‍ය වීම වළක්වා ගත හැක."),
        q("මීමැස්මොරය හෙවත් අපස්මාරය (Seizure / Epilepsy) සෑදී වලිප්පුවෙන් ගැහෙන රෝගියෙකුට කිසිසේත්ම නොකළ යුත්තේ කුමක්ද?", "යකඩ යතුරු හෝ හැඳි කට තුළට දැමීම සහ රෝගියා බලහත්කාරයෙන් අල්ලා තද කිරීම", "හිසට කොට්ටයක් තැබීම", "අවට අනතුරුදායක බඩු ඉවත් කිරීම", "ඇඳුම් ලිහිල් කිරීම", "කටට යකඩ දැමීමෙන් දත් කැඩී ශ්වාසනාලයේ සිරවිය හැකි අතර බලෙන් තද කිරීමෙන් අස්ථි බිඳී යා හැක."),
        q("වලිප්පුව හෙවත් ගැස්ම නතර වූ පසු මීමැස්මොර රෝගියා තැබිය යුතු වඩාත් සුදුසු ඉරියව්ව කුමක්ද?", "සෝදිසි ඉරියව්ව (Recovery position)", "උඩුබැලි අතට තැබීම", "වාඩි කරවීම", "සිටුවා තැබීම", "වලිප්පුවෙන් පසු රෝගියා නිදිමත තත්ත්වයට පත්වන බැවින් කෙළ හෝ වමනය ගිලීම වැළැක්වීමට සෝදිසි ඉරියව්වේ තබයි."),
        q("ප්‍රථමාධාරයේදී විෂබීජහරණය කළ ගෝස් කැබැල්ලක් (Sterile gauze) සෘජුව තුවාලය මත තැබීම හඳුන්වන්නේ කෙසේද?", "තුවාල ආවරණය හෙවත් ඩ්‍රෙසිං (Dressing)", "වෙළුම් පටිය (Bandage)", "එල්ලනය (Sling)", "දැවතිය (Splint)", "Dressing සෘජුව තුවාලය ආවරණය කර ලේ උරා ගන්නා අතර Bandage මගින් එය රඳවා තබයි."),
        q("ඩ්‍රෙසිං (Dressing) සහ බැන්ඩේජ් (Bandage) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "ඩ්‍රෙසිං සෘජුව තුවාලය මත තබන අතර බැන්ඩේජ් මගින් ඩ්‍රෙසිං එක තද කර රඳවා තබයි", "ඩ්‍රෙසිං ගැටගැසීමට පමණක් භාවිත කිරීම", "බැන්ඩේජ් සෘජුව තුවාලය තුළට දැමීම", "කිසිදු වෙනසක් නොමැති වීම", "තුවාලය මත තබන පිරිසිදු පෑඩය ඩ්‍රෙසිං වන අතර එය තබා බඳින පටිය බැන්ඩේජ් වේ."),
        q("පපුවේ විවෘත තුවාලයකින් (Sucking chest wound) හුස්ම ගන්නා විට බුබුළු දමමින් ශබ්ද නගන අවස්ථාවක කළ යුතු ප්‍රථමාධාරය කුමක්ද?", "තුවාලයේ පැති 3ක් පමණක් ආවරණය වන පරිදි ප්ලාස්ටික් කොළයක් අලවා එක් පැත්තක් විවෘතව තැබීම (Three-sided dressing)", "තුවාලය සම්පූර්ණයෙන්ම විවෘතව තැබීම", "තුවාලය ඇතුළට ඇඟිල්ල දැමීම", "රෝගියා මුනින්තලා කිරීම", "පැති 3ක් වැසූ විට පිටත වාතය පපුවට ඇතුළු වීම වැළකෙන අතර ඇතුළත පීඩනය පිටවීමට එක් පැත්තක් කපාටයක් සේ ක්‍රියා කරයි."),
        q("උදරයේ බිත්තිය කැපී බඩවැල් කොටස් පිටතට නෙරා ආ විට ප්‍රථමාධාරකරු කළ යුත්තේ කුමක්ද?", "බඩවැල් ඇතුළට තල්ලු නොකර තෙත විෂබීජහරණය කළ රෙදිකඩකින් ආවරණය කිරීම", "බඩවැල් බලහත්කාරයෙන් ආපසු ඇතුළට එබීම", "බඩවැල් වියළෙන්නට හැරීම", "අයිස් කෙළින්ම බඩවැල් මත තැබීම", "නෙරා ආ අවයව වියළීම වැළැක්වීමට තෙත රෙද්දකින් වසා කිසිසේත් ඇතුළට නොතල්ලු කළ යුතුය."),
        q("කනෙන් පැහැදිලි දියරයක් (මස්තිෂ්ක සුෂුම්නා තරලය — CSF) කාන්දු වීම මගින් පෙන්නුම් කරන්නේ කුමන බරපතළ හානියක්ද?", "හිස්කබල පාදස්ථයේ අස්ථි බිඳීමක් (Base of skull fracture)", "කණේ ආසාදනයක් පමණි", "නාසයේ පීනස", "දත් කැක්කුමක්", "හිසට පහරක් වැදී කනෙන් හෝ නාසයෙන් ලේ හෝ වතුර වැනි CSF තරලය ඒම හිස්කබල බිඳීමේ ලක්ෂණයකි."),
        q("ඇස් දෙක වටා කණ්නාඩි දැමූ ආකාරයෙන් කළු පැහැ ගැන්වීම (Raccoon eyes) පෙන්නුම් කරන්නේ කුමක්ද?", "හිස්කබල අස්ථි බිඳීමක්", "ඇසේ සුද", "නින්ද මදිවීම", "සෙම්ප්‍රතිශ්‍යාව", "හිස්කබල පාදයේ බිඳීමකදී ඇස් වටා ලේ එකතු වී පැන්ඩා ඇස් හෙවත් රැකූන් අයිස් ලක්ෂණය මතුවේ."),
        q("කන පිටුපස බීජාකාර අස්ථිය මත නිල් පැහැ ලපයක් මතුවීම (Battle's sign) අඟවන්නේ කුමක්ද?", "හිස්කබලේ පසුපස අස්ථි බිඳීමක්", "කම්මුල්ගාය", "කන් කැක්කුම", "උගුරේ ආසාදනය", "හිස්කබලේ පාදස්ථ අස්ථි බිඳීමකදී කන පිටුපස මැස්ටොයිඩ් අස්ථිය මත තැලුම් ලපයක් මතුවේ."),
        q("හෘදයාබාධයකදී (Heart attack) රෝගියාට දැනෙන ප්‍රධානතම රෝග ලක්ෂණය කුමක්ද?", "පපුව මැද තද වන දැඩි වේදනාව සහ එම වේදනාව වම් අත හෝ හකුපාඩ දෙසට විහිදී යාම", "දකුණු පාදයේ ඇඟිලි කැක්කුම", "බඩගින්න", "ඇස් පෙනීම වැඩිවීම", "පපුව මත අධික බරක් තබා ඇති සේ දැනෙන වේදනාව වම් උරහිස, බෙල්ල හා හනුව දෙසට පැතිර යයි."),
        q("හෘදයාබාධයක් යැයි සැක කරන සිහිය ඇති රෝගියෙකු තැබිය යුතු වඩාත් පහසු ඉරියව්ව කුමක්ද?", "අර්ධ හිඳි ඉරියව්ව හෙවත් ඩබ්ලිව් ඉරියව්ව (W position / Half-sitting position)", "මුණින්තලා කර තැබීම", "කෙළින්ම සිටුවා තැබීම", "පාද ඔසවා උඩුබැලි අතට තැබීම", "පිටුපසට ආධාරක තබා දණහිස් මඳක් නවා අර්ධව වාඩි කරවීමෙන් හෘදයට ඇතිවන ආතතිය අවම වේ."),
        q("අංශභාගය හෙවත් ආඝාතය (Stroke) හඳුනාගැනීමට භාවිත කරන FAST හි F අකුරෙන් විමසන්නේ කුමක්ද?", "මුහුණේ එක් පැත්තක් ඇද වී පහතට වැටී ඇත්දැයි බැලීම (Face drooping)", "උණ පරීක්ෂාව (Fever)", "පාදයේ චලනය (Foot)", "හෘද ස්පන්දනය (Fast heart)", "මුහුණේ එක පැත්තක් පණ නැති වී සිනාසෙන විට ඇද වීම ආඝාතයේ ප්‍රධාන ලක්ෂණයකි."),
        q("FAST පරීක්ෂාවේ A අකුරෙන් පරීක්ෂා කරන්නේ රෝගියාගේ කුමන ක්‍රියාවද?", "දෑත් දෙකම ඉහළට ඔසවා තබාගත හැකිදැයි බැලීම (Arm weakness)", "ඇස් පෙනීම (Accuracy)", "කන් ඇසීම (Auditory)", "ආහාර රුචිය (Appetite)", "එක් අතක් පණ නැතිව පහළට වැටීම හෝ එසවීමට නොහැකි වීම ස්නායු ආඝාතයේ ලක්ෂණයකි."),
        q("FAST හි S අකුරෙන් නියෝජනය වන්නේ කුමක්ද?", "කතා කිරීම අපැහැදිලි හෝ පැටලෙන්නේදැයි බැලීම (Speech difficulty)", "සම සුදුමැලි වීම", "හුස්ම ගැනීම", "සීනි මට්ටම", "වචන උච්චාරණය කිරීමට නොහැකි වීම හෝ කතා බහ පැටලීම ආඝාතයේ සලකුණකි."),
        q("FAST හි T අකුරෙන් ලබාදෙන ප්‍රමුඛ පණිවිඩය කුමක්ද?", "ක්ෂණිකව කාලය නාස්ති නොකර ගිලන් රථයක් කැඳවීම (Time to call emergency)", "පෙති වර්ග බීම", "උෂ්ණත්වය මැනීම", "තුවාල පරීක්ෂාව", "මොළයේ සෛල මියයාම වැළැක්වීමට ආඝාත රෝගියෙකු පැය කිහිපයක් ඇතුළත රෝහල්ගත කළ යුතුය."),
        q("ශ්‍රී ලංකාවේ නොමිලේ ලබාදෙන ජාතික සුවසැරිය සුවසත්කාර ගිලන්රථ සේවයේ හදිසි ඇමතුම් අංකය කුමක්ද?", "1990", "119", "110", "1919", "1990 සුවසැරිය සේවාව හරහා වෛද්‍ය කාර්ය මණ්ඩල සහිත පූර්ව රෝහල් ප්‍රතිකාර ගිලන්රථ නොමිලේ ලැබේ."),
        q("ශ්‍රී ලංකා පොලිස් හදිසි ආපදා ඇමතුම් අංකය කුමක්ද?", "119", "1990", "110", "1999", "ඕනෑම හදිසි අපරාධ හෝ මහජන ආරක්ෂක අනතුරකදී 119 අංකයෙන් පොලිසිය අමතයි."),
        q("ගිනි නිවීම් හා ගලවා ගැනීමේ සේවාව සඳහා අමතන හදිසි දුරකථන අංකය කුමක්ද?", "110", "119", "1990", "1912", "ගිනි ගැනීම් හා හදිසි ගලවා ගැනීම් සඳහා 110 ක්ෂණික අංකය භාවිත වේ."),
        q("ප්‍රථමාධාර පෙට්ටියක (First Aid Box) අඩංගු විය යුතු අත්‍යවශ්‍ය මූලික උපකරණයක් නොවන්නේ කුමක්ද?", "ශල්‍යකර්ම පිහි සහ නිර්වින්දන ඖෂධ", "විෂබීජහරණය කළ ගෝස් පෑඩ්", "ත්‍රිකෝණාකාර වෙළුම් පටි", "කතුර සහ අත්වැසුම්", "ප්‍රථමාධාර පෙට්ටියක සංකීර්ණ ශල්‍ය උපකරණ හෝ නිර්වින්දන ඖෂධ නොතිබිය යුතුය."),
        q("ප්‍රථමාධාර පෙට්ටිය තැබිය යුතු වඩාත් සුදුසු ස්ථානය කුමක්ද?", "පහසුවෙන් ළඟාවිය හැකි, කුඩා දරුවන්ට අසුනොවන, වියළි සිසිල් ස්ථානයක", "තදින් අගුළු දැමූ අල්මාරියක යටම", "මුළුතැන්ගෙයි ලිප අසල", "අව්ව වැටෙන ජනෙල් පඩිය මත", "හදිසි අවස්ථාවකදී ක්ෂණිකව ගත හැකි එහෙත් දරුවන්ට අනතුරක් නොවන තැනක තැබිය යුතුය."),
        q("ක්‍රීඩාවේදී සිදුවන ආබාධ අවම කර ගැනීම සඳහා ක්‍රීඩාවට පෙර කළ යුතු අනිවාර්ය ක්‍රියාකාරකම කුමක්ද?", "ක්‍රමානුකූල උණුසුම් වීමේ හා ඇදීමේ ව්‍යායාමවල නිරත වීම (Warm-up & Stretching)", "අධික ලෙස ආහාර ගැනීම", "ඖෂධ පානය කිරීම", "සම්පූර්ණ නිශ්චලව සිටීම", "උණුසුම් වීමෙන් මාංශ පේශිවලට රුධිර සැපයුම වැඩි වී නම්‍යශීලී බව වැඩි වීමෙන් ආබාධ වළකී."),
        q("දැඩි ක්‍රීඩා පුහුණුවකින් හෝ තරගයකින් පසු ශරීරය සාමාන්‍ය තත්ත්වයට පත් කිරීම සඳහා කළ යුත්තේ කුමක්ද?", "ක්‍රමානුකූලව සිසිල් වීමේ ව්‍යායාමවල යෙදීම (Cool-down / Warm-down)", "වහාම සීතල වතුරෙන් ස්නානය කිරීම", "එකවරම බිම වාඩි වී නිදා ගැනීම", "තද ආහාර වේලක් ගැනීම", "සිසිල් වීම මගින් පේශිවල රැස් වූ ලැක්ටික් අම්ලය ඉවත් වී පසු ආබාධ හා තද ගතිය නැති වේ."),
        q("ක්‍රීඩකයෙකු ක්‍රීඩා කරන විට සුදුසු ආරක්ෂක ආම්පන්න (Shin guards, Helmets, Mouthguards) පැළඳීමේ වැදගත්කම කුමක්ද?", "අනතුරු හා බරපතළ ආබාධ ඇතිවීමේ අවදානම අවම කර ගැනීම", "විලාසිතාව ප්‍රදර්ශනය කිරීම", "වේගය අඩු කිරීම", "විරුද්ධ පිල බිය ගැන්වීම", "හිස් ආවරණ, පා ආවරණ හා දත් ආවරණ මගින් ප්‍රධාන අවයවවලට එල්ල වන පහර අවශෝෂණය කරයි."),
        q("පාසල් ක්‍රීඩා පිටියේ ආරක්ෂාව තහවුරු කිරීමට ක්‍රීඩා භාර ආචාර්යවරයා කළ යුතු පූර්ව පරීක්ෂාව කුමක්ද?", "පිටියේ වීදුරු කටු, ගල්, වලවල් හෝ අනතුරුදායක යකඩ කොටස් තිබේදැයි පරීක්ෂා කිරීම", "පිටියට ජලය පිරවීම", "පිටිය සම්පූර්ණයෙන්ම වසා දැමීම", "ශබ්ද විකාශන යන්ත්‍ර පරීක්ෂාව පමණි", "ක්‍රීඩා පිටියේ අනතුරුදායක බාධක ඉවත් කිරීමෙන් බොහෝ බරපතළ වැටීම් හා කැපුම් වළක්වා ගත හැක."),
        q("ක්‍රීඩා තරගයකදී හෝ පාගමනකදී ප්‍රමාණවත් පරිදි ජලය පානය නොකිරීමෙන් හටගන්නා ප්‍රධාන අනතුර කුමක්ද?", "විජලනය (Dehydration) හා මාංශ පේශි පෙරළීම", "අධික බර වැඩිවීම", "අස්ථි වර්ධනය", "රුධිරය වැඩිවීම", "දහඩිය මගින් ජලය හා ලවණ පිටවීම පිරිමැසීමට ප්‍රමාණවත් ජලය නොබීමෙන් විජලනය වේ."),
        q("ප්‍රථමාධාර ලබාදීමේදී ප්‍රථමාධාරකරු සතු විය යුතු වැදගත්ම සදාචාරාත්මක ගුණාංගය කුමක්ද?", "රෝගියාගේ රහස්‍යභාවය හා ගෞරවය සුරකිමින් අපක්ෂපාතීව කරුණාවෙන් සත්කාර කිරීම", "රෝගියාගේ ඡායාරූප සමාජ මාධ්‍යවල පළ කිරීම", "මුදල් අය කිරීම", "අන්‍යයන්ට දොස් පැවරීම", "ජාති, ආගම් හෝ තරාතිරම නොබලා රෝගියාගේ මානව ගරුත්වය සුරැකීම ප්‍රථමාධාරකරුගේ වගකීමකි."),
        q("හදිසි අනතුරකදී තුවාලකරුවන් කිහිප දෙනෙකු සිටින විට ප්‍රතිකාර සඳහා ප්‍රමුඛතාව තීරණය කිරීමේ ක්‍රමය කුමක්ද?", "ට්‍රියාජ් ක්‍රමය හෙවත් ප්‍රමුඛතා වර්ගීකරණය (Triage system)", "වයස අනුව පෝලිම් ගැස්වීම", "කැමති අනුපිළිවෙළට තෝරා ගැනීම", "ලොතරැයි ඇදීම", "ජීවිතය අනතුරේ ඇති වඩාත්ම බරපතළ රෝගීන්ට ප්‍රමුඛතාව දී වෙන් කර ප්‍රතිකාර කිරීම Triage ක්‍රමයයි."),
        q("හදිසි ආපදාවකදී ට්‍රියාජ් (Triage) ක්‍රමය යටතේ රතු පැහැති ටැගය (Red Tag) මගින් සංකේතවත් කරන්නේ කුමන රෝගීන් කාණ්ඩයද?", "ක්ෂණික හදිසි ප්‍රතිකාර අවශ්‍ය ජීවිත අවදානම් සහිත බරපතළ රෝගීන් (Immediate)", "සුළු තුවාල සහිත අය", "ප්‍රතිකාර ප්‍රමාද කළ හැකි අය", "මියගිය අය", "රතු පැහැති ටැගය මගින් ක්ෂණිකව ජීවිතය බේරා ගැනීමේ ප්‍රතිකාර අවශ්‍ය බරපතළම රෝගීන් හඳුන්වයි."),
        q("ට්‍රියාජ් ක්‍රමයේදී කහ පැහැති ටැගය (Yellow Tag) මගින් වර්ගීකරණය කරන්නේ කෙබඳු තුවාලකරුවන්ද?", "පැය කිහිපයක් ප්‍රතිකාර ප්‍රමාද කළ හැකි මධ්‍යස්ථ බරපතළ රෝගීන් (Delayed)", "ක්ෂණික ප්‍රතිකාර ලබන්නන්", "සුළු සීරීම් ඇති අය", "මියගිය අය", "කහ පැහැති රෝගීන්ට බරපතළ තුවාල ඇතත් පැය 2-4ක් වැනි කෙටි කාලයක් ප්‍රතිකාර ප්‍රමාද කළ හැක."),
        q("ට්‍රියාජ් ක්‍රමයේදී කොළ පැහැති ටැගය (Green Tag) මගින් හඳුන්වන්නේ කුමන තත්ත්වයේ පුද්ගලයන්ද?", "සුළු තුවාල සහිත තනිව ඇවිදිය හැකි තුවාලකරුවන් (Minor / Walking wounded)", "බරපතළ රෝගීන්", "සිහිසුන් රෝගීන්", "මියගිය අය", "කොළ පැහැති කාණ්ඩය සුළු තුවාල සහිත තනිව ගමන් කළ හැකි අඩු අවදානම් සහිත පුද්ගලයන්ය."),
        q("ට්‍රියාජ් ක්‍රමයේ කළු පැහැති ටැගය (Black Tag) මගින් අදහස් කෙරෙන්නේ කුමක්ද?", "මියගිය හෝ බේරාගත නොහැකි මරණාසන්න තත්ත්වයේ සිටින පුද්ගලයන් (Deceased)", "සුළු තුවාලකරුවන්", "ක්ෂණික ශල්‍යකර්ම අවශ්‍ය අය", "නිරෝගී අය", "කළු පැහැය මරණයට පත් වූ හෝ ප්‍රතිකාරවලින් බේරාගත නොහැකි අයට යොදයි."),
        q("රසායනික ද්‍රව්‍යයක් ඇඟ මත වැටුණු විට ප්‍රථමාධාරකරු වහාම ඉවත් කළ යුතු දේ කුමක්ද?", "රසායනික ද්‍රව්‍ය තැවරුණු සියලුම ඇඳුම් පැළඳුම්", "සපත්තු පමණක්", "ඔරලෝසුව පමණක්", "හිස්වැස්ම පමණක්", "රසායනික තැවරුණු ඇඳුම් දිගටම සම මත පැවතීමෙන් පිළිස්සීම උග්‍ර වන බැවින් වහාම ඉවත් කළ යුතුය."),
        q("අස්ථියක් බිඳී ඇති බවට සැක කරන විට ක්‍රීඩා පිටියේදී අස්ථිය කැඩී ඇත්දැයි බැලීමට ඇටකටු එහා මෙහා සෙලවීම නුසුදුසු වන්නේ මන්ද?", "තියුණු අස්ථි තුඩුවලින් ප්‍රධාන රුධිර වාහිනී හෝ ස්නායු කැපී යා හැකි බැවින්", "වේදනාව අඩු වන නිසා", "එය සාමාන්‍ය පරීක්ෂාවක් නිසා", "අස්ථි එකතු වන නිසා", "කැඩුණු අස්ථි කැබලි සෙලවීමෙන් මාංශ පේශි හා ස්නායු ඉරී ගොස් ආබාධය දරුණු වේ."),
        q("පාසලේ විද්‍යාගාරයේ අම්ලයක් (Acid) ශරීරයේ තැවරුණු විට එය උදාසීන කිරීමට ක්ෂාර වර්ග දැමීම නොකළ යුත්තේ මන්ද?", "උදාසීනීකරණ ප්‍රතික්‍රියාවේදී විශාල තාපයක් පිටවී දෙවනුව තාප පිළිස්සීමක් ඇතිවන බැවින්", "අම්ලය තවත් ප්‍රබල වන නිසා", "ක්ෂාරවලින් සුව වන නිසා", "කිසිදු ප්‍රතික්‍රියාවක් සිදුනොවන නිසා", "උදාසීනීකරණය තාපදායක ප්‍රතික්‍රියාවක් බැවින් ඇතිවන තාපයෙන් තුවාලය වඩාත් බරපතළ වේ."),
        q("රෝගියෙකුගේ ශරීරයේ සිරවී ඇති යකඩ කූරක් හෝ ලී කැබැල්ලක් වටා යෙදිය යුතු වෙළුම් ක්‍රමය කුමක්ද?", "වළලු හැඩයේ ආධාරකයක් (Ring pad) තබා ඒ වටා වෙළුම් යෙදීම", "වස්තුව මතින් කෙළින්ම වෙළීම", "වස්තුව ඇද ඉවත් කර වෙළීම", "වෙළුම් නොදැමීම", "ඇනී ඇති වස්තුව නොසෙල්වෙන පරිදි මුදු හැඩැති රෙදි ආධාරකයක් තබා වෙළනු ලැබේ."),
        q("හිස ප්‍රදේශයේ අභ්‍යන්තර ලේ ගැලීමක් හෙවත් මොළයේ රුධිර වහනයක් (Subdural / Epidural haematoma) සැක කළ හැකි ඇසේ සලකුණ කුමක්ද?", "ඇසේ කනිනිකා (Pupils) දෙක අසමාන ප්‍රමාණයෙන් තිබීම", "ඇස් දෙකම රතු වීම", "ඇස් පෙනීම වැඩිවීම", "කඳුළු ගැලීම", "මොළය තුළ පීඩනය වැඩිවීමේදී ස්නායු තෙරපී ඇසේ එක් කනිනිකාවක් අනෙකට වඩා විශාල වේ."),
        q("පිහිනුම් තටාකයේ පතුලේ වැදී බෙල්ල කැඩුණු ක්‍රීඩකයෙකු ජලයෙන් ගොඩගත යුත්තේ කෙසේද?", "ජලය තුළදීම කොඳු ඇට පෙළ සහ බෙල්ල සරල රේඛාවක නිශ්චල කර තබා පාවෙන ආධාරකයක් මතින්", "කකුල් දෙකෙන් අල්ලා ගොඩට ඇදීමෙන්", "අත් දෙකෙන් ඔසවාගෙන ඒමෙන්", "ජලයෙන් එළියට විසි කිරීමෙන්", "ජලය තුළදීම බෙල්ල හා හිස නොසෙල්වෙන සේ අල්ලාගෙන පාවෙන ස්පයිනල් බෝඩ් එකක් මතට ගත යුතුය."),
        q("ශරීරයේ විශාල ප්‍රදේශයක් පිලිස්සුණු රෝගියෙකු රෝහලට ගෙන යන විට විෂබීජ ආසාදන වැළැක්වීමට ආවරණය කළ හැකි සරල ගෘහස්ථ ද්‍රව්‍යය කුමක්ද?", "පිරිසිදු ක්ලින්ග් රැප් (Cling film) හෙවත් ආහාර ඔතන ප්ලාස්ටික් කොළය", "පත්තර කඩදාසි", "තෙල් කඩදාසි", "කපු රෙදි කැබලි", "ක්ලින්ග් රැප් තුවාලයේ නොඇලෙන අතර විෂබීජ හා වාතය ස්පර්ශ වීම වළක්වා වේදනාව අඩු කරයි."),
        q("පිළිස්සුම් තුවාලයකට කපු පුළුන් (Cotton wool) කෙළින්ම නොතැබිය යුත්තේ මන්ද?", "පුළුන් කෙඳි පිළිස්සුණු පටකවල තදින් ඇලී ඉවත් කිරීමේදී දැඩි වේදනාවක් හා පටක හානි සිදුවන බැවින්", "පුළුන් දියවන නිසා", "පුළුන්වලින් රස්නය වැඩිවන නිසා", "කිසිදු හානියක් නැති නිසා", "කපු පුළුන් කෙඳි තුවාලයේ ඇලී ආසාදන ඇති කරන බැවින් කිසිවිටෙකත් කෙළින්ම නොතැබිය යුතුය."),
        q("මී උණ (Leptospirosis) ආසාදනය විය හැකි බැක්ටීරියාව සිරුරට ඇතුළු වන්නේ කුමන ආකාරයෙන්ද?", "කැපුම් හෝ සීරීම් තුවාල සහිත සම මත මී මුත්‍ර මිශ්‍ර ජලය හෝ මඩ තැවරීමෙන්", "මදුරුවන් දෂ්ට කිරීමෙන්", "හුස්ම ගැනීමෙන්", "ආහාර පිසීමෙන්", "මඩ කුඹුරු හා කානු ආශ්‍රිත ජලයේ ඇති ලෙප්ටොස්පයිරා බැක්ටීරියාව තුවාල හරහා සිරුරට ඇතුළු වේ."),
        q("ජලභීතිකා (Rabies) රෝග ලක්ෂණ පහළ වූ පසු රෝගියාගේ මරණ අනුපාතිකය කොපමණද?", "100%ක්ම මාරාන්තික වේ", "50%ක් පමණි", "10%ක් පමණි", "සුව කළ හැක", "ජලභීතිකා රෝග ලක්ෂණ මතු වූ පසු එයින් බේරීමට ප්‍රතිකාර නොමැති තරම්ය. එබැවින් එන්නත කලින්ම ලබාගත යුතුය."),
        q("බල්ලෙකු සපා කෑ විට සපා කෑ සුනඛයා නිරීක්ෂණය කළ යුතු අවම දින ගණන කීයද?", "දින 10 සිට 14 දක්වා කාලයක්", "දින 2ක්", "මාස 3ක්", "පැය 24ක්", "සුනඛයාට ජලභීතිකාව ඇත්නම් ඌ දින 10-14ක් ඇතුළත රෝග ලක්ෂණ පෙන්වා මියයයි."),
        q("සපා කෑ බල්ලා දින 10ක් ඇතුළත මියගියහොත් හෝ අතුරුදහන් වුවහොත් කළ යුතු අනිවාර්ය පියවර කුමක්ද?", "රෝගියාට සම්පූර්ණ ජලභීතිකා මර්දන එන්නත් මාලාව (PEP) කඩිනමින් ලබාදීම", "කිසිදු ප්‍රතිකාරයක් නොගැනීම", "තුවාලය කැපීම", "පැරසිටමෝල් පමණක් බීම", "සත්ත්වයා අතුරුදහන් වුවහොත් හෝ මියගියහොත් වහාම පූර්ණ ජලභීතිකා එන්නත් මාලාව ලබාගත යුතුය."),
        q("අතේ ඉහළ බාහුව (Humerus) අස්ථිය බිඳී ගිය විට අත පපුවට තබා ආධාරකයක් ලබාදෙන වෙළුම කුමක්ද?", "කරපටි සහ අත්වාරු වෙළුම හෙවත් කොලර් ඇන්ඩ් කෆ් එල්ලනය (Collar and cuff sling)", "විශාල අත් එල්ලනය", "උස් අත් එල්ලනය", "පාද වෙළුම", "මැණික් කටුව ආධාරක කරමින් ඉහළ බාහුවේ බරින් කැඩුණු අස්ථිය කෙළින් තබා ගැනීමට මෙය යොදා ගනී."),
        q("පාදයේ කලවා අස්ථිය (Femur) බිඳී ගිය විට සුදුසු දැවති නොමැති නම් ආධාරකයක් ලෙස භාවිත කළ හැක්කේ කුමක්ද?", "රෝගියාගේම අනෙක් නිරෝගී පාදය ආධාරකයක් ලෙස තබා දෙපා එකට බැඳීම", "අත ආධාරක කර ගැනීම", "කොට්ටයක් පමණක් තැබීම", "ඇවිද්දවීම", "නිරෝගී පාදය ස්වභාවික ශක්තිමත් ආධාරකයක් (Anatomical splint) ලෙස භාවිත කළ හැක."),
        q("පාදයේ දණහිස් සන්ධිය හෝ විලුඹ සන්ධිය උළුක්කු වූ විට මුල් පැය කිහිපයේදී පීඩන වෙළුම (Compression) දැමිය යුතු නිවැරදි දිශාව කුමක්ද?", "ඇඟිලි තුඩු දෙස සිට හෘදය දෙසට ඉහළට වෙළාගෙන යාම", "ඉහළ සිට පහළට වෙළීම", "මැද සිට දෙපසට වෙළීම", "කැමති අතකට වෙළීම", "කෙළවර සිට හෘදය දෙසට වෙළීමෙන් ශිරා රුධිරය ආපසු ගලා ඒම පහසු වේ."),
        q("ඇඟිලි දෙස සිට ඉහළට වෙළීමේ ජීව විද්‍යාත්මක වැදගත්කම කුමක්ද?", "කෙළවර කොටස්වල තරල හා රුධිරය හෘදය දෙසට ගලා ඒමට උපකාරී වී ඉදිමීම පාලනය වීම", "බැන්ඩේජ් එක ඉක්මනින් ඉවර වීම", "අලංකාරය වැඩිවීම", "වේදනාව වැඩිවීම", "පිටත සිට ඇතුළට වෙළීමෙන් ඉදිමුම් තරල පහළ එකතු වීම වැළකේ."),
        q("අතක් හෝ පාදයක් වෙළුම් පටියකින් බැඳීමෙන් පසු රුධිර සංසරණය ඇණහිට ඇත්දැයි බැලීමට ඇඟිලි නියපොත්ත තද කර මුදා හැරීමේ පරීක්ෂාව කුමක්ද?", "කේශනාලිකා නැවත පිරවීමේ පරීක්ෂාව (Capillary Refill Test — CRT)", "ස්පන්දන පරීක්ෂාව", "රුධිර පීඩන පරීක්ෂාව", "ස්නායු පරීක්ෂාව", "නියපොත්ත තද කළ විට සුදුමැලි වන අතර මුදාහළ පසු සාමාන්‍ය රුධිරය ගලා ඒම CRT පරීක්ෂාවයි."),
        q("කේශනාලිකා නැවත පිරවීමේ පරීක්ෂාවේදී (CRT) නියපොත්ත රෝස පැහැයට හැරීමට ගත විය යුතු සාමාන්‍ය කාලය කොපමණද?", "තත්පර 2කට වඩා අඩු කාලයක්", "තත්පර 10ක්", "විනාඩියක්", "තත්පර 5ක්", "සාමාන්‍ය රුධිර සංසරණය පවතී නම් තත්පර 2ක් ඇතුළත නියපොත්ත නැවත රෝස පැහැ වේ."),
        q("වෙළුම් පටියක් දැමූ පසු අත් පා ඇඟිලි නිල් වීම, සීතල වීම හෝ හිරිවැටීම පෙන්නුම් කරන්නේ කුමක්ද?", "වෙළුම් පටිය ඕනෑවට වඩා තද වී රුධිර සංසරණය අවහිර වී ඇති බව", "තුවාලය සුව වන බව", "අස්ථි වර්ධනය වන බව", "ප්‍රතිකාරය සාර්ථක බව", "ඇඟිලි නිල් වීම හා සීතල වීමෙන් හැඟවෙන්නේ ධමනි හෝ ශිරා අවහිර වී ඇති බවයි."),
        q("වෙළුම් පටිය තද වැඩි බව පෙනී ගිය වහාම ප්‍රථමාධාරකරු කළ යුත්තේ කුමක්ද?", "වෙළුම් පටිය ලිහිල් කර නැවත මධ්‍යස්ථ පීඩනයකින් යුතුව බැඳීම", "වෙළුම තවත් තද කිරීම", "අත කපා දැමීම", "කිසිවක් නොකර සිටීම", "පටක මියයාම වැළැක්වීමට වහාම වෙළුම ලිහිල් කර නැවත නිවැරදිව බැඳිය යුතුය."),
        q("ප්‍රථමාධාරයේදී ත්‍රිකෝණාකාර වෙළුම් පටියක (Triangular Bandage) පාදස්ථය (Base) සහ අග්‍රය (Apex) සම්බන්ධයෙන් වඩාත් දිගම පැත්ත කුමක්ද?", "පාදස්ථය හෙවත් කර්ණය (Base)", "කෙටි පැත්ත", "අග්‍රය", "සියලු පැති සමානය", "ත්‍රිකෝණාකාර වෙළුමක දිගම පැත්ත පාදස්ථය (Base) වන අතර ඊට විරුද්ධ මුදුන අග්‍රය (Apex) වේ."),
        q("ත්‍රිකෝණාකාර වෙළුම් පටියක් නැවීමෙන් සාදා ගන්නා පළල් පටිය හඳුන්වන්නේ කෙසේද?", "පුළුල් වෙළුම හෙවත් බ්‍රෝඩ් බැන්ඩේජ් (Broad bandage)", "පටු වෙළුම", "අටේ වෙළුම", "කරපටි වෙළුම", "අග්‍රය පාදස්ථය දෙසට දෙවරක් නැමීමෙන් පළල් වෙළුම (Broad bandage) සාදා ගනී."),
        q("ත්‍රිකෝණාකාර වෙළුම් පටියක් තවදුරටත් අඩකින් නවා සාදා ගන්නා පටු පටිය කුමක්ද?", "පටු වෙළුම හෙවත් නැරෝ බැන්ඩේජ් (Narrow bandage)", "පළල් වෙළුම", "එල්ලනය", "දැවතිය", "පළල් වෙළුම තවත් වරක් නැමූ විට පටු වෙළුම (Narrow bandage) ලැබේ."),
        q("උරහිස හෝ ඉඟටිය ආශ්‍රිත විශාල සන්ධියක තුවාලයක් ආවරණය කිරීමට භාවිත කරන වෙළුම කුමක්ද?", "ස්පයිකා වෙළුම (Spica bandage)", "චක්‍රාකාර වෙළුම", "සර්පිලාකාර වෙළුම", "ප්‍රත්‍යාවර්තක වෙළුම", "සිරුරේ කඳ සහ අත් පා එකතු වන විශාල සන්ධි සඳහා ස්පයිකා වෙළුම යොදා ගැනේ."),
        q("ගෙල සිරවීමකින් (Strangulation / Hanging) අනතුරට ලක් වූ අයෙකු දුටු වහාම කළ යුතු ප්‍රථම පියවර කුමක්ද?", "සිරුර ඔසවා තබා ගෙල වටා ඇති ලණුව හෝ පටිය වහාම කපා ඉවත් කිරීම", "පොලිසිය එනතුරු බලා සිටීම", "ඡායාරූප ගැනීම", "සිරුර බිමට ඇද දැමීම", "පළමුව සිරුරේ බරින් ගෙල තෙරපීම වළක්වා ලණුව කපා හුස්ම ගැනීමේ මාර්ගය නිදහස් කළ යුතුය."),
        q("ළිඳකට හෝ සංවෘත කාමරයකට බැසීමේදී විෂ වායු (කාබන් මොනොක්සයිඩ්, මීතේන්) ආඝ්‍රාණයෙන් සිහිසුන් වූ අයෙකු බේරාගැනීමට පෙර කළ යුත්තේ කුමක්ද?", "ප්‍රමාණවත් වාතාශ්‍රයක් ලබාදී තමාට ඔක්සිජන් ආවරණ නොමැතිව එම වළට නොබැසීම", "වහාම වළට පැනීම", "ගිනි දැල්වීම", "ජලය පිරවීම", "ප්‍රථමාධාරකරුද විෂ වායුවෙන් සිහිසුන් විය හැකි බැවින් ආරක්ෂිත ක්‍රමවේද අනුගමනය කළ යුතුය."),
        q("කාබන් මොනොක්සයිඩ් (CO) වායුව ආඝ්‍රාණය වීම මාරාන්තික වන්නේ මන්ද?", "හිමොග්ලොබින් සමග ඔක්සිජන්වලට වඩා 200 ගුණයකට වඩා ප්‍රබලව බැඳී ඔක්සිජන් ප්‍රවාහනය අඩපණ කරන බැවින්", "පෙනහලු පුපුරුවා හරින නිසා", "උගුර කසන නිසා", "ලේ වියළන නිසා", "කාබන් මොනොක්සයිඩ් හිමොග්ලොබින් සමග කාබොක්සිහිමොග්ලොබින් සාදා පටකවලට ඔක්සිජන් යාම සම්පූර්ණයෙන් අවහිර කරයි."),
        q("අකුණු සහිත වැසි අවස්ථාවක එළිමහන් ක්‍රීඩා පිටියක සිටින විට අනුගමනය කළ යුතු ආරක්ෂිතම ඉරියව්ව කුමක්ද?", "හුදකලා උස් ගස් යටට නොගොස් විවෘත බිමක පාද දෙක එකට තබා දණහිස් නමා බිම පහත් වී හිස නවා ගැනීම", "උසම ගසක් යටට දිව යාම", "බිම සම්පූර්ණයෙන්ම දිගා වීම", "කුඩයක් ඉහළාගෙන සිටීම", "අකුණු අනතුරේදී දෙපා එකට තබා බිම පහත් වීමෙන් (Lightning crouch) භූගත ධාරා සිරුරට ඇතුළු වීම අවම වේ."),
        q("අකුණු ගසන විට විවෘත බිමක සම්පූර්ණයෙන්ම දිගා වී නිදා නොගත යුත්තේ මන්ද?", "පොළොව මතුපිටින් ගලා යන භූගත ධාරා (Ground currents) නිසා ශරීරයට විදුලි සැර වැදීමේ ඉඩකඩ වැඩි වන බැවින්", "සීතල වැඩිවන නිසා", "ඇඳුම් අපිරිසිදු වන නිසා", "කිසිදු අනතුරක් නැති නිසා", "බිම දිගා වූ විට ශරීරයේ විශාල පෘෂ්ඨයක් පොළොවේ ගැටෙන බැවින් භූගත ධාරා ශරීරය හරහා ගලා යා හැක."),
        q("පාසල් බස් රථයක හෝ වාහනයක ගමන් කරන විට ආසන පටි (Seat belts) පැළඳීමේ වැදගත්කම කුමක්ද?", "හදිසි තිරිංග යෙදීමකදී හෝ ගැටුමකදී මගීන් ඉදිරියට විසි වී වීදුරුවල හෝ බඳෙහි ගැටීම වැළැක්වීම", "ඇඳුම් රැලි නොවැටී තබා ගැනීම", "නින්ද යාම වැළැක්වීම", "විලාසිතාවක් ලෙස", "ආසන පටිය මගින් ශරීරයේ චලිත ශක්තිය අවශෝෂණය කර බරපතළ විසිවීම් හා හිසේ තුවාල වළක්වයි."),
        q("යතුරුපැදි පදින්නන් හා පසුපස ගමන් කරන්නන් සම්මත ආරක්ෂක හිස්වැසුම් (Helmets) පැළඳිය යුත්තේ මන්ද?", "රිය අනතුරකදී හිස්කබල බිඳීම හා මොළයට සිදුවන මාරාන්තික හානි අවම කර ගැනීමට", "පොලිස් දඩවලින් බේරීමට පමණක්", "සුළඟ වැදීම වැළැක්වීමට", "හිරු එළියෙන් බේරීමට", "හිස්වැස්ම අනතුරකදී කම්පනය අවශෝෂණය කර මොළයට සිදුවන විනාශකාරී හානි වළක්වා ජීවිතය බේරා දෙයි."),
        q("පාසල් රසායනාගාරයේදී අත්හදා බැලීම් කරන විට ඇස් ආවරණ (Safety goggles) සහ අත් ආවරණ පැළඳීමේ ප්‍රධාන අරමුණ කුමක්ද?", "විෂ රසායනික ද්‍රව්‍ය ඇසට විසිවීම සහ සම පිළිස්සීම වළක්වා ගැනීම", "පෙනුම ලස්සන කර ගැනීමට", "විදුලියෙන් ආරක්ෂා වීමට", "ඇස් පෙනීම වැඩි කර ගැනීමට", "විද්‍යාගාර අත්හදා බැලීම්වලදී අනපේක්ෂිත රසායනික විසිරීම්වලින් ඇස් හා සම ආරක්ෂා කරගත යුතුය."),
        q("නිවෙස්වල ළමුන්ට අතපසුවීම්වලින් සිදුවන ඖෂධ විෂවීම් වළක්වා ගැනීමට ගත හැකි හොඳම ක්‍රියාමාර්ගය කුමක්ද?", "සියලුම ඖෂධ කුඩා ළමුන්ට ළඟාවිය නොහැකි උස අගුළු දැමූ පෙට්ටියක තැබීම", "ඖෂධ බිම තැබීම", "ඖෂධ ශීතකරණයේ පහළම තට්ටුවේ තැබීම", "පැණි බීම බෝතල්වල ඖෂධ දැමීම", "ඖෂධ දරුවන්ට අසු නොවන සේ ආරක්ෂිතව තැබීමෙන් අත්වැරදීම්වලින් සිදුවන විෂවීම් වළක්වා ගත හැක."),
        q("උග්‍ර බඩගින්න හෝ දැඩි විජලනය නිසා පාසල් උදෑසන රැස්වීමේදී සිසුන් ක්ලාන්ත වීමට ප්‍රධාන හේතුව කුමක්ද?", "මොළයට ලැබෙන රුධිරය හා ඔක්සිජන් ප්‍රමාණය තාවකාලිකව අඩුවීම", "විටමින් අධික වීම", "අධික නින්ද", "ශරීරයේ බර අඩුවීම", "උදෑසන ආහාර නොගැනීමෙන් රුධිර සීනි මට්ටම සහ රුධිර පීඩනය පහත වැටී මොළයට ඔක්සිජන් හිඟ වීමෙන් ක්ලාන්තය හටගනී."),
        q("පාසල් පරිසරයේදී හදිසි ගිනි අනතුරක් ඇතිවූ විට සිසුන් ගොඩනැගිල්ලෙන් ඉවත් විය යුතු ආකාරය කුමක්ද?", "කලබල නොවී පේළි ගැසී නියමිත හදිසි පිටවීමේ දොරටු ඔස්සේ විවෘත රැස්වීම් භූමියට (Assembly point) යාම", "කෑගසමින් දොරටු දෙසට පොරකෑම", "පන්ති කාමරවල මේස යට සැඟවීම", "පොත් බෑග් එකතු කිරීම", "ගිනි අනතුරකදී තෙරපීම් වැළැක්වීමට විනයගරුකව නියමිත ඉවත් වීමේ සැලැස්ම (Evacuation plan) අනුගමනය කළ යුතුය."),
        q("දුමාරය පිරුණු කාමරයකින් පිටතට පැමිණිය යුතු ආරක්ෂිතම ආකාරය කුමක්ද?", "උණුසුම් දුම හා විෂ වායු ඉහළට නගින බැවින් බිම දිගේ බඩගාමින් ඉදිරියට යාම", "සෘජුව සිටගෙන දිවීම", "ඇස් පියාගෙන සිටීම", "පැන පැන ගමන් කිරීම", "විෂ වායු හා උණුසුම් දුම කාමරයේ ඉහළ මට්ටමේ පවතින බැවින් පිරිසිදු වාතය ඇත්තේ බිම් මට්ටමේය."),
        q("රෝහල් හදිසි ප්‍රතිකාර ඒකකයට ඇතුළත් කිරීමට පෙර රෝගියෙකුගේ තත්ත්වය නිරීක්ෂණය කරන විට සටහන් කරගත යුතු මූලික ජීව දත්ත මොනවාද?", "නාඩි වේගය, හුස්ම ගැනීමේ වේගය, සිහි මට්ටම සහ සමේ ස්වභාවය", "ශරීරයේ උස සහ පාදයේ ප්‍රමාණය", "අඳින ඇඳුම්වල මිල", "ලේ ඥාතීන්ගේ නම්", "මූලික ජීව දත්ත (Vital signs) මගින් රෝගියාගේ ශරීරයේ අත්‍යවශ්‍ය අවයවවල ක්‍රියාකාරිත්වය පෙන්නුම් කරයි."),
        q("වැඩිහිටි නිරෝගී පුද්ගලයෙකුගේ සාමාන්‍ය විවේකී නාඩි වේගය (Pulse rate) විනාඩියකට ස්පන්දන කීයක්ද?", "විනාඩියකට ස්පන්දන 60 සිට 100 දක්වා", "විනාඩියකට 30 සිට 40 දක්වා", "විනාඩියකට 120 සිට 180 දක්වා", "විනාඩියකට 10 සිට 20 දක්වා", "නිරෝගී වැඩිහිටියෙකුගේ හෘද ස්පන්දන වේගය සාමාන්‍යයෙන් විනාඩියකට වාර 60-100 අතර පරාසයක පවතී."),
        q("වැඩිහිටි නිරෝගී පුද්ගලයෙකුගේ සාමාන්‍ය ශ්වසන වේගය (Respiratory rate) විනාඩියකට වාර කීයක්ද?", "විනාඩියකට වාර 12 සිට 20 දක්වා", "විනාඩියකට වාර 30 සිට 50 දක්වා", "විනාඩියකට වාර 5ක් පමණි", "විනාඩියකට වාර 60 සිට 80 දක්වා", "නිරෝගී වැඩිහිටියෙකු විවේකී අවස්ථාවේ විනාඩියකට 12-20 වාරයක් සාමාන්‍ය ලෙස හුස්ම ගනී."),
        q("රෝගියෙකුගේ නාඩි පරීක්ෂා කිරීමේදී මහපටැඟිල්ල භාවිත නොකළ යුත්තේ මන්ද?", "පරීක්ෂකයාගේම මහපටැඟිල්ලේ ප්‍රබල ස්පන්දනයක් ඇති බැවින් රෝගියාගේ නාඩිය සමග පැටලිය හැකි නිසා", "මහපටැඟිල්ලේ විෂබීජ ඇති නිසා", "මහපටැඟිල්ල කෙටි නිසා", "කිසිදු හේතුවක් නැත", "පරීක්ෂකයාගේ මහපටැඟිල්ලේ ඇති ධමනියේ ස්පන්දනය රෝගියාගේ ස්පන්දනය යැයි වරදවා වටහා ගත හැකි බැවින් දබරඟිල්ල හා මැදඟිල්ල භාවිත කළ යුතුය."),
        q("ක්‍රීඩා ක්ෂේත්‍රයේදී ප්‍රථමාධාර දැනුම සෑම පුහුණුකරුවෙකුට හා ක්‍රීඩකයෙකුටම අත්‍යවශ්‍ය වන්නේ මන්ද?", "ක්‍රීඩා ආබාධ කඩිනමින් හඳුනාගෙන නිවැරදි ක්ෂණික සත්කාර දී ක්‍රීඩකයාගේ අනාගත ක්‍රීඩා දිවිය රැකගැනීමට හැකි බැවින්", "තරග ජයග්‍රහණය කිරීමට පමණක්", "වෛද්‍ය වියදම් සම්පූර්ණයෙන් නැති කිරීමට", "ක්‍රීඩා ඇඳුම් සැලසුම් කිරීමට", "ක්ෂණික හා නිවැරදි ප්‍රථමාධාර මගින් බරපතළ ක්‍රීඩා ආබාධ සුව කර ක්‍රීඩකයාගේ ක්‍රීඩා දිවිය සුරක්ෂිත කළ හැක.")
    )
}
